#!/usr/bin/env node
// mutation-scope — diff-scoped Stryker run (generated by Nous, IMP-344 / L1).
//
// ONE campaign over the files this branch actually changed, instead of a
// whole-tree run or a hand-chained per-story sequence. The common case — a diff
// with nothing mutatable — exits 0 in milliseconds without starting Stryker.
//
// Scope is the DIFF, filtered to mutatable source files. Deliberately NOT
// intersected with the critical set: nothing declares critical source *paths*,
// and guessing them could only drop a changed critical file from the run. The
// critical set decides which STORIES owe mutation evidence (see
// docs/dev-guide/TESTING.md §3), not which files get mutated.
//
// Env overrides:
//   MUTATION_BASE=<ref>   compare against this ref instead of the default branch
//   MUTATION_SCOPE_DRY=1  write + print the generated config, do NOT run Stryker
import { execFileSync, spawn, spawnSync } from "node:child_process";
import { createHash, randomUUID } from "node:crypto";
import { copyFileSync, existsSync, mkdirSync, readFileSync, realpathSync, rmSync, statSync, writeFileSync } from "node:fs";
import os from "node:os";
import { basename, dirname, join, relative, resolve, sep } from "node:path";
import { pathToFileURL } from "node:url";
import ts from "../apps/web/node_modules/typescript/lib/typescript.js";
import {
  cacheRoot,
  projectMutationReportArtifact,
  readCacheEntry,
  writeSuccessfulCacheEntry,
} from "./mutation-evidence/cache.mjs";
import { canonicalJson, collectExecutionInputs, createEvidenceKey, sha256 } from "./mutation-evidence/fingerprint.mjs";
import {
  createPerformanceRun,
  finishPerformanceRun,
  finishShard,
  startShard,
  writePerformanceRecord,
} from "./mutation-evidence/performance.mjs";
import { validatePoolProjectionEvidence } from "./verify-pool-snapshot-projection.mjs";

const BASE_CONFIG = "stryker.conf.json";
const GENERATED_SHARD_DIR = join(".tmp", "stryker-shards");
const GENERATED_MANIFEST = join(GENERATED_SHARD_DIR, "manifest.json");
const SCHEMA_STATIC_SOURCE = "packages/db/src/schema.ts";
const VITEST_CONFIG_STATIC_SOURCE = "apps/web/vitest.config.ts";
const VITEST_CONFIG_STATIC_RANGE = `${VITEST_CONFIG_STATIC_SOURCE}:21-21`;
const SCORED_STATIC_KINDS = new Set(["schema-static", "vitest-config-static"]);
const EXACT_FRAMEWORK_ADAPTER_KIND = "exact-framework-adapter";
const MUTATION_RUNNER_STATIC_INPUTS = [
  "scripts/mutation-scope.mjs",
  "scripts/mutation-evidence/fingerprint.mjs",
  "scripts/mutation-evidence/cache.mjs",
  "scripts/mutation-evidence/performance.mjs",
];
const POOL_PROJECTION_STATIC_INPUTS = [
  "scripts/verify-pool-snapshot-projection.mjs",
];

// Mirrors stryker.conf.json's mutate globs: which files can carry mutants.
// This is a FILE-TYPE filter, not a critical-set narrowing — a changed `.md` or
// `.json` has no mutants, so excluding it removes nothing real.
const MUTATABLE_EXT = /\.(ts|tsx)$/;
const GENERATED_ARTIFACT = [
  /(^|\/)\.tmp\//,
  /(^|\/)\.next\//,
  /(^|\/)(coverage|dist|reports)\//,
];
const EXCLUDED = [
  /\.(test|spec)\.tsx?$/,
  /\.d\.ts$/,
  /(^|\/)e2e\//,
  /(^|\/)playwright\.config\.(ts|js|mts|mjs)$/,
  /(^|\/)migrations\//,
  /(^|\/)testing\//,
  /(^|\/)node_modules\//,
  ...GENERATED_ARTIFACT,
];

function git(args) {
  return execFileSync("git", args, { encoding: "utf8" }).trim();
}

/** A git call whose FAILURE is an expected, handled outcome (probing for a ref
 *  that may not exist). git writes `fatal: ...` to stderr even when the caller
 *  copes, so stderr is discarded here — otherwise every run in a repo without
 *  `origin/HEAD` prints a scary line that is not an error. Real failures still
 *  surface: the caller decides, via the thrown exception. */
function gitProbe(args) {
  return execFileSync("git", args, {
    encoding: "utf8", stdio: ["ignore", "pipe", "ignore"],
  }).trim();
}

/** Fail LOUD. A mutation run that cannot determine its scope must NOT report
 *  success having mutated nothing — a silent empty scope is a false green. */
function fail(message, hint) {
  console.error(`mutation-scope: ${message}`);
  if (hint) console.error(`  ${hint}`);
  process.exit(2);
}

/** The ref to diff against. Resolved, never hardcoded to `main`: a repo whose
 *  trunk is `master`, or a CI checkout with a different default, must not
 *  silently produce an empty diff. */
function resolveBase() {
  if (process.env.MUTATION_BASE) {
    const ref = process.env.MUTATION_BASE;
    try {
      gitProbe(["rev-parse", "--verify", "--quiet", ref]);
      return ref;
    } catch {
      fail(`MUTATION_BASE=${ref} does not resolve to a ref`,
           "check the ref name, or unset MUTATION_BASE to use the default branch");
    }
  }
  try {
    // origin/HEAD is the authoritative default branch when a remote exists.
    const sym = gitProbe(["symbolic-ref", "--short", "refs/remotes/origin/HEAD"]);
    if (sym) return sym;
  } catch { /* no remote / no origin/HEAD — fall through to local trunks */ }
  for (const ref of ["main", "master"]) {
    try {
      gitProbe(["rev-parse", "--verify", "--quiet", ref]);
      return ref;
    } catch { /* try the next candidate */ }
  }
  fail("cannot resolve a default branch to diff against (tried origin/HEAD, main, master)",
       "set MUTATION_BASE=<ref> explicitly");
}

function changedFiles(base) {
  const mergeBase = mergeBaseFor(base);
  // Diff directly from the merge base so committed, staged, and unstaged
  // changes are all visible. Git diff does not report untracked files, so add
  // every non-ignored untracked path explicitly. Otherwise a newly created
  // production module can silently escape the pre-commit mutation gate.
  // ACMR excludes deletions: Stryker cannot mutate a file that is gone.
  const tracked = git(["diff", "--name-only", "--diff-filter=ACMR", mergeBase]);
  const untracked = git(["ls-files", "--others", "--exclude-standard"]);
  return [...new Set(
    [tracked, untracked]
      .flatMap((value) => value ? value.split("\n") : [])
      .filter(Boolean)
      .filter((path) => !GENERATED_ARTIFACT.some((pattern) => pattern.test(path))),
  )].sort();
}

function mergeBaseFor(base) {
  try {
    return gitProbe(["merge-base", "HEAD", base]);
  } catch {
    // A shallow clone or an unrelated history has no merge base. Exiting 0 here
    // would mutate nothing and report success — the false green this guard
    // exists to prevent.
    fail(`no merge base between HEAD and ${base}`,
         "unshallow the clone (git fetch --unshallow) or set MUTATION_BASE=<ref>");
  }
}

export function mutatable(files) {
  return files
    .filter((f) => MUTATABLE_EXT.test(f))
    .filter((f) => !EXCLUDED.some((re) => re.test(f)))
    .sort();  // deterministic: the generated config must be byte-stable
}

function lineCount(contents) {
  if (contents.length === 0) return 0;
  const lines = contents.split(/\r?\n/);
  return lines.length - (lines.at(-1) === "" ? 1 : 0);
}

export function mutationTargetsFromPatch(patch, untracked = new Map()) {
  const targets = [];
  let source = null;
  for (const line of patch.split("\n")) {
    if (line.startsWith("+++ ")) {
      const path = line.slice(4);
      source = path === "/dev/null"
        ? null
        : path.startsWith("b/") ? path.slice(2) : path;
      continue;
    }
    if (!source || !line.startsWith("@@ ")) continue;
    const hunk = /\+(\d+)(?:,(\d+))?/.exec(line);
    if (!hunk) continue;
    const start = Number(hunk[1]);
    const count = hunk[2] === undefined ? 1 : Number(hunk[2]);
    if (count > 0) targets.push(`${source}:${start}-${start + count - 1}`);
  }
  for (const [path, count] of untracked) {
    if (count > 0) targets.push(`${path}:1-${count}`);
  }
  return [...new Set(targets)].sort();
}

export function mutationHunksFromPatch(patch, contentsForSource) {
  const hunks = [];
  let source = null;
  let current = null;
  const finish = () => {
    if (current) hunks.push({
      ...current,
      oldContents: contentsForSource(current.source).oldContents,
      newContents: contentsForSource(current.source).newContents,
    });
    current = null;
  };
  for (const line of patch.split("\n")) {
    if (line.startsWith("+++ ")) {
      source = line.slice(4).replace(/^b\//, "");
      continue;
    }
    if (line.startsWith("@@ ")) {
      finish();
      const header = /-(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))?/.exec(line);
      if (!header || !source) throw new Error(`cannot parse mutation hunk: ${line}`);
      current = {
        source,
        oldStart: Number(header[1]),
        oldLines: [],
        newStart: Number(header[3]),
        newLines: [],
      };
      continue;
    }
    if (!current) continue;
    if (line.startsWith("-") && !line.startsWith("---")) current.oldLines.push(line.slice(1));
    if (line.startsWith("+") && !line.startsWith("+++")) current.newLines.push(line.slice(1));
  }
  finish();
  return hunks;
}

export function mutationSourceFiles(targets) {
  return [...new Set(
    targets.map((target) => target.replace(/:\d+-\d+$/, "")),
  )].sort();
}

/** Stryker interprets mutate paths with minimatch even when they carry an
 * exact line range. Escape bracketed Next.js route segments so a literal
 * `[vendorAccountId]` directory cannot be treated as a character class. */
export function strykerMutationTarget(target) {
  return target.replace(/[\[\]]/g, (bracket) => bracket === "[" ? "[[]" : "[]]");
}

export function groupRoutedMutationTargets(targets, routeTestsForSource) {
  const groups = new Map();
  for (const source of mutationSourceFiles(targets)) {
    const testFiles = [...new Set(routeTestsForSource(source))].sort();
    if (testFiles.length === 0) {
      throw new Error(`mutatable source has no responsible Vitest test route: ${source}`);
    }
    const key = JSON.stringify(testFiles);
    const group = groups.get(key) ?? { mutate: [], sources: [], testFiles };
    group.sources.push(source);
    group.mutate.push(
      ...targets.filter((target) => target.replace(/:\d+-\d+$/, "") === source),
    );
    groups.set(key, group);
  }
  return [...groups.values()]
    .map((group) => ({
      mutate: [...new Set(group.mutate)].sort(),
      sources: [...new Set(group.sources)].sort(),
      testFiles: group.testFiles,
    }))
    .sort((left, right) =>
      JSON.stringify(left.sources).localeCompare(JSON.stringify(right.sources)) ||
      JSON.stringify(left.testFiles).localeCompare(JSON.stringify(right.testFiles)));
}

function parseModule(source, contents) {
  const parsed = ts.createSourceFile(
    source,
    contents,
    ts.ScriptTarget.Latest,
    true,
    source.endsWith(".tsx") ? ts.ScriptKind.TSX : ts.ScriptKind.TS,
  );
  if (parsed.parseDiagnostics.length > 0) {
    throw new Error(`verification-only candidate has parse errors: ${source}`);
  }
  return parsed;
}

function sourcePackageRoot(source) {
  const segments = source.split("/");
  return segments[0] === "packages" || segments[0] === "apps"
    ? join(segments[0], segments[1])
    : segments[0];
}

function relativeModuleTarget(source, specifier, fileExists) {
  if (!specifier.startsWith("./") && !specifier.startsWith("../")) {
    throw new Error(`verification-only module specifier is not relative: ${specifier}`);
  }
  const unresolved = join(dirname(source), specifier.replace(/\.js$/, ""));
  const candidates = [
    `${unresolved}.ts`,
    `${unresolved}.tsx`,
    join(unresolved, "index.ts"),
    join(unresolved, "index.tsx"),
  ].filter(fileExists);
  if (candidates.length !== 1) {
    throw new Error(
      `verification-only module specifier resolves ${candidates.length} targets: ${specifier}`,
    );
  }
  const canonicalize = fileExists === existsSync ? realpathSync : resolve;
  const repositoryRoot = canonicalize(resolve("."));
  const packageRoot = canonicalize(resolve(sourcePackageRoot(source)));
  const resolvedCandidate = canonicalize(resolve(candidates[0]));
  if (
    relative(repositoryRoot, resolvedCandidate).startsWith(`..${sep}`) ||
    relative(packageRoot, resolvedCandidate).startsWith(`..${sep}`)
  ) {
    throw new Error(`verification-only module target escapes its package: ${specifier}`);
  }
  return candidates[0];
}

function moduleDeclarations(parsed) {
  return parsed.statements.filter((node) =>
    (ts.isImportDeclaration(node) || ts.isExportDeclaration(node)) &&
    node.moduleSpecifier && ts.isStringLiteral(node.moduleSpecifier));
}

function declarationOnLine(parsed, lineNumber, predicate) {
  const matches = moduleDeclarations(parsed).filter((node) => {
    if (!predicate(node)) return false;
    const token = node.moduleSpecifier;
    const start = parsed.getLineAndCharacterOfPosition(token.getStart(parsed)).line + 1;
    const end = parsed.getLineAndCharacterOfPosition(token.getEnd()).line + 1;
    return start === lineNumber && end === lineNumber;
  });
  if (matches.length !== 1) {
    throw new Error(`verification-only hunk has ${matches.length} exact module declarations`);
  }
  return matches[0];
}

function assertNoImportAttributes(node) {
  if (node.attributes || node.assertClause) {
    throw new Error("verification-only module declaration cannot use attributes or assertions");
  }
}

function assertRawJsAppend(oldNode, newNode, oldParsed, newParsed, oldLine, newLine) {
  assertNoImportAttributes(oldNode);
  assertNoImportAttributes(newNode);
  const oldToken = oldNode.moduleSpecifier.getText(oldParsed);
  const newToken = newNode.moduleSpecifier.getText(newParsed);
  if (
    oldToken.length < 3 ||
    newToken !== `${oldToken.slice(0, -1)}.js${oldToken.slice(-1)}` ||
    oldLine.replace(oldToken, "<module>") !== newLine.replace(newToken, "<module>")
  ) {
    throw new Error("verification-only module edit must solely insert .js before the unchanged closing quote");
  }
  return newNode.moduleSpecifier.text;
}

function fingerprint(lines) {
  return createHash("sha256").update(lines.join("\n")).digest("hex");
}

function contentHash(contents) {
  return createHash("sha256").update(contents).digest("hex");
}

export function normalizeMutationConfigIdentity(config) {
  return {
    ...config,
    tempDirName: "<mutation-temp-dir>",
    htmlReporter: { ...config.htmlReporter, fileName: "<mutation-report-html>" },
    jsonReporter: { ...config.jsonReporter, fileName: "<mutation-report-json>" },
  };
}

function rangeParts(target) {
  const match = /^(.*):(\d+)-(\d+)$/.exec(target);
  if (!match) throw new Error(`invalid mutation range: ${target}`);
  return { source: match[1], start: Number(match[2]), end: Number(match[3]) };
}

export function validateMutationReportIdentity(
  report,
  shard,
  actualConfigText,
  sourceContents,
) {
  let actualConfig;
  try {
    actualConfig = JSON.parse(actualConfigText);
  } catch {
    throw new Error(`mutation config is malformed: ${shard.id}`);
  }
  const normalizedConfigHash = contentHash(
    `${JSON.stringify(normalizeMutationConfigIdentity(actualConfig), null, 2)}\n`,
  );
  if (contentHash(actualConfigText) !== shard.configHash && normalizedConfigHash !== shard.configHash) {
    throw new Error(`mutation config hash mismatch: ${shard.id}`);
  }
  for (const [source, expectedHash] of Object.entries(shard.contentHashes)) {
    if (contentHash(sourceContents(source)) !== expectedHash) {
      throw new Error(`mutation source content hash mismatch: ${source}`);
    }
  }
  if (
    JSON.stringify(report?.config?.mutate) !== JSON.stringify(shard.mutate) ||
    report?.config?.configFile !== shard.configPath ||
    report?.config?.jsonReporter?.fileName !== shard.jsonReportPath
  ) {
    throw new Error(`mutation report config identity mismatch: ${shard.id}`);
  }
  const ranges = shard.mutate.map(rangeParts);
  const reportedSources = Object.keys(report?.files ?? {}).sort();
  const reportMutants = mutationReportMutants(report);
  if (
    reportMutants.length > 0 &&
    JSON.stringify(reportedSources) !== JSON.stringify([...shard.sources].sort())
  ) {
    throw new Error(`mutation report source identity mismatch: ${shard.id}`);
  }
  for (const [source, file] of Object.entries(report?.files ?? {})) {
    if (!shard.sources.includes(source)) {
      throw new Error(`mutation report contains unexpected source: ${source}`);
    }
    if (typeof file?.source !== "string" || contentHash(file.source) !== shard.contentHashes[source]) {
      throw new Error(`mutation report embedded source hash mismatch: ${source}`);
    }
    for (const mutant of file?.mutants ?? []) {
      const start = mutant.location?.start?.line;
      const end = mutant.location?.end?.line;
      if (!ranges.some((range) =>
        range.source === source && Number.isInteger(start) && Number.isInteger(end) &&
        start >= range.start && end <= range.end)) {
        throw new Error(`mutation report mutant is outside requested ranges: ${source}`);
      }
    }
  }
  return true;
}

/** Classify only the two AST shapes that are inherently non-mutatable:
 * an existing relative import whose sole token edit appends `.js`, or a newly
 * added exact `export * from` declaration. Any mixed, unresolved, ambiguous,
 * or parse-invalid hunk throws instead of silently escaping mutation. */
export function classifyVerificationOnlyHunk(change, fileExists = existsSync) {
  const {
    source, oldContents, newContents,
    oldStart, oldLines, newStart, newLines,
  } = change;
  const oldParsed = parseModule(source, oldContents);
  const newParsed = parseModule(source, newContents);
  let reason;
  let specifier;

  if (oldLines.length === 1 && newLines.length === 1) {
    const oldNode = declarationOnLine(oldParsed, oldStart, ts.isImportDeclaration);
    const newNode = declarationOnLine(newParsed, newStart, ts.isImportDeclaration);
    specifier = assertRawJsAppend(
      oldNode, newNode, oldParsed, newParsed, oldLines[0], newLines[0],
    );
    reason = "relative-import-appends-js";
  } else if (oldLines.length >= 1 && oldLines.length === newLines.length) {
    const resolvedTargets = [];
    for (let index = 0; index < oldLines.length; index += 1) {
      const predicate = (candidate) => ts.isExportDeclaration(candidate) &&
        candidate.exportClause === undefined && !candidate.isTypeOnly;
      const oldNode = declarationOnLine(oldParsed, oldStart + index, predicate);
      const newNode = declarationOnLine(newParsed, newStart + index, predicate);
      const nextSpecifier = assertRawJsAppend(
        oldNode, newNode, oldParsed, newParsed, oldLines[index], newLines[index],
      );
      resolvedTargets.push(relativeModuleTarget(source, nextSpecifier, fileExists));
    }
    return {
      newFingerprint: fingerprint(newLines),
      oldFingerprint: fingerprint(oldLines),
      range: `${source}:${newStart}-${newStart + newLines.length - 1}`,
      reason: "relative-export-stars-append-js",
      resolvedTarget: resolvedTargets,
    };
  } else if (oldLines.length === 0 && newLines.length >= 1) {
    const resolvedTargets = [];
    for (let index = 0; index < newLines.length; index += 1) {
      const node = declarationOnLine(
        newParsed,
        newStart + index,
        (candidate) => ts.isExportDeclaration(candidate) &&
          candidate.exportClause === undefined && !candidate.isTypeOnly,
      );
      assertNoImportAttributes(node);
      const exactNodeText = node.getText(newParsed);
      if (newLines[index].trim() !== exactNodeText) {
        throw new Error("verification-only re-export hunk must contain only exact export declarations");
      }
      resolvedTargets.push(relativeModuleTarget(source, node.moduleSpecifier.text, fileExists));
    }
    return {
      newFingerprint: fingerprint(newLines),
      oldFingerprint: fingerprint(oldLines),
      range: `${source}:${newStart}-${newStart + newLines.length - 1}`,
      reason: "new-relative-export-stars",
      resolvedTarget: resolvedTargets,
    };
  } else {
    throw new Error("verification-only hunk is mixed or spans unsupported lines");
  }

  const resolvedTarget = relativeModuleTarget(source, specifier, fileExists);
  return {
    newFingerprint: fingerprint(newLines),
    oldFingerprint: fingerprint(oldLines),
    range: `${source}:${newStart}-${newStart + newLines.length - 1}`,
    reason,
    resolvedTarget,
  };
}

const POOL_PROJECTION_SOURCE = "packages/db/src/pool-snapshots.ts";
const POOL_PROJECTION_DELTAS = [
  { line: 6, oldLines: [], newLines: ["  readonly effectiveFrom: string;"] },
  { line: 22, oldLines: [], newLines: ["  effective_from: string;"] },
  {
    line: 51,
    oldLines: [],
    newLines: ["            capacity.effective_from::text AS effective_from,"],
  },
  {
    line: 57,
    oldLines: ["              vac.license_type_id, vac.purchased_qty"],
    newLines: [
      "              vac.license_type_id, vac.purchased_qty, vac.effective_from",
    ],
  },
  { line: 107, oldLines: [], newLines: ["    effectiveFrom: row.effective_from,"] },
];

function exactNamedInterfaceProperty(parsed, interfaceName, propertyName) {
  const interfaces = parsed.statements.filter((node) =>
    ts.isInterfaceDeclaration(node) && node.name.text === interfaceName);
  if (interfaces.length !== 1) {
    throw new Error(`database projection wrong scope: expected one ${interfaceName} interface`);
  }
  const properties = interfaces[0].members.filter((node) =>
    ts.isPropertySignature(node) && ts.isIdentifier(node.name) &&
    node.name.text === propertyName);
  if (properties.length !== 1) {
    throw new Error(`database projection missing or duplicate ${interfaceName}.${propertyName}`);
  }
  const [property] = properties;
  if (
    property.questionToken || property.initializer ||
    property.type?.kind !== ts.SyntaxKind.StringKeyword
  ) {
    throw new Error(`database projection ${interfaceName}.${propertyName} has a cast or default`);
  }
}

/** Verify the one inherently non-mutatable US-023 database projection bundle.
 * This is deliberately bound to a single source, function, field pair, and
 * complete five-delta patch; it is not a general SQL or data-wiring escape. */
export function classifyPoolSnapshotProjectionBundle(changes) {
  if (!Array.isArray(changes)) {
    throw new Error("database projection incomplete exact five-delta bundle");
  }
  if (new Set(changes.map((change) => change.newStart)).size !== changes.length) {
    throw new Error("database projection duplicate range");
  }
  if (changes.length !== POOL_PROJECTION_DELTAS.length) {
    throw new Error("database projection incomplete exact five-delta bundle");
  }
  if (changes.some((change) => change.source !== POOL_PROJECTION_SOURCE)) {
    throw new Error("database projection wrong scope");
  }
  const ordered = [...changes].sort((left, right) => left.newStart - right.newStart);
  for (let index = 0; index < POOL_PROJECTION_DELTAS.length; index += 1) {
    const change = ordered[index];
    const expected = POOL_PROJECTION_DELTAS[index];
    if (change.newStart !== expected.line) {
      throw new Error("database projection incomplete or extra range set");
    }
    if (
      JSON.stringify(change.oldLines) !== JSON.stringify(expected.oldLines) ||
      JSON.stringify(change.newLines) !== JSON.stringify(expected.newLines)
    ) {
      throw new Error("database projection mixed or renamed delta");
    }
  }
  const newContents = ordered[0].newContents;
  const oldContents = ordered[0].oldContents;
  if (ordered.some((change) =>
    change.newContents !== newContents || change.oldContents !== oldContents)) {
    throw new Error("database projection mixed source snapshots");
  }
  let reconstructedOld = newContents;
  for (const delta of [...POOL_PROJECTION_DELTAS].reverse()) {
    const next = `${delta.newLines.join("\n")}\n`;
    const previous = delta.oldLines.length === 0
      ? ""
      : `${delta.oldLines.join("\n")}\n`;
    const matches = reconstructedOld.split(next).length - 1;
    if (matches !== 1) {
      throw new Error("database projection missing, duplicate, or extra delta");
    }
    reconstructedOld = reconstructedOld.replace(next, previous);
  }
  if (reconstructedOld !== oldContents) {
    throw new Error("database projection mixed or extra edit");
  }

  const parsed = parseModule(POOL_PROJECTION_SOURCE, newContents);
  exactNamedInterfaceProperty(parsed, "SeatPoolCountsSnapshot", "effectiveFrom");
  exactNamedInterfaceProperty(parsed, "SeatPoolRow", "effective_from");
  const functions = parsed.statements.filter((node) =>
    ts.isFunctionDeclaration(node) && node.name?.text === "listCurrentSeatPoolCounts");
  if (functions.length !== 1 || !functions[0].body) {
    throw new Error("database projection wrong scope: listCurrentSeatPoolCounts");
  }
  let queryTemplate;
  let mappedPropertyCount = 0;
  const visit = (node) => {
    if (
      ts.isCallExpression(node) && ts.isPropertyAccessExpression(node.expression) &&
      node.expression.name.text === "query" && node.arguments.length >= 1
    ) {
      if (queryTemplate) throw new Error("database projection extra query in function scope");
      queryTemplate = node.arguments[0];
    }
    if (
      ts.isPropertyAssignment(node) && ts.isIdentifier(node.name) &&
      node.name.text === "effectiveFrom"
    ) {
      mappedPropertyCount += 1;
      if (
        !ts.isPropertyAccessExpression(node.initializer) ||
        !ts.isIdentifier(node.initializer.expression) ||
        node.initializer.expression.text !== "row" ||
        node.initializer.name.text !== "effective_from"
      ) {
        throw new Error("database projection row mapping wrong or has a default");
      }
    }
    ts.forEachChild(node, visit);
  };
  visit(functions[0].body);
  if (mappedPropertyCount !== 1) {
    throw new Error("database projection row mapping missing or duplicate");
  }
  if (!queryTemplate || !ts.isNoSubstitutionTemplateLiteral(queryTemplate)) {
    throw new Error("database projection interpolation or non-static SQL");
  }
  const sqlText = queryTemplate.text;
  const requireOnce = (fragment, fault) => {
    if (sqlText.split(fragment).length - 1 !== 1) {
      throw new Error(`database projection ${fault}`);
    }
  };
  requireOnce(
    "capacity.effective_from::text AS effective_from",
    "outer projection removed, renamed, cast, or duplicated",
  );
  requireOnce(
    "vac.license_type_id, vac.purchased_qty, vac.effective_from",
    "lateral field removed, reordered, or duplicated",
  );
  requireOnce(
    "SELECT DISTINCT ON (vac.license_type_id)",
    "DISTINCT pairing removed or duplicated",
  );
  requireOnce(
    "ORDER BY vac.license_type_id, vac.effective_from DESC,\n                vac.created_at DESC, vac.id DESC",
    "ORDER pairing removed, changed, or duplicated",
  );

  return {
    faultIds: [
      "outer-projection-removed-or-renamed",
      "lateral-field-removed",
      "row-mapping-wrong",
      "operating-date-input-replaced",
      "operating-date-constant",
    ],
    ranges: ordered.map((change) =>
      `${change.source}:${change.newStart}-${change.newStart + change.newLines.length - 1}`),
    reason: "verification-only:database-projection-bundle",
    source: POOL_PROJECTION_SOURCE,
  };
}

