const PAGE_WIRING_SOURCES = new Set(Object.keys(PAGE_WIRING_SPECS));

function exactNamedImports(parsed, expectedNames) {
  const declarations = moduleDeclarations(parsed).filter((node) =>
    ts.isImportDeclaration(node) && node.moduleSpecifier.text === "./labels");
  if (declarations.length !== 1) {
    throw new Error("page wiring missing, wrong, or duplicate labels import");
  }
  const clause = declarations[0].importClause;
  if (
    !clause || clause.name || !clause.namedBindings ||
    !ts.isNamedImports(clause.namedBindings)
  ) {
    throw new Error("page wiring labels import must use exact named imports");
  }
  const names = clause.namedBindings.elements.map((element) => element.name.text).sort();
  if (JSON.stringify(names) !== JSON.stringify([...expectedNames].sort())) {
    throw new Error("page wiring labels import has missing, renamed, or extra bindings");
  }
}

function jsxAttribute(element, name) {
  const attributes = element.attributes.properties.filter((property) =>
    ts.isJsxAttribute(property) && property.name.getText() === name);
  if (attributes.length !== 1 || !attributes[0].initializer ||
      !ts.isJsxExpression(attributes[0].initializer) ||
      !attributes[0].initializer.expression) {
    throw new Error(`page wiring ${name} prop missing, duplicate, or non-expression`);
  }
  return attributes[0].initializer.expression;
}

export function classifyPageWiringBundle(changes) {
  if (!Array.isArray(changes) || changes.length === 0) {
    throw new Error("page wiring incomplete bundle");
  }
  const sources = new Set(changes.map((change) => change.source));
  if (sources.size !== 1) throw new Error("page wiring bundle must be file-specific");
  const source = [...sources][0];
  const spec = PAGE_WIRING_SPECS[source];
  if (!spec) throw new Error("page wiring wrong scope");
  if (changes.length !== spec.deltas.length) {
    throw new Error("page wiring incomplete or extra hunk set");
  }
  if (new Set(changes.map((change) => change.newStart)).size !== changes.length) {
    throw new Error("page wiring duplicate hunk");
  }
  const ordered = [...changes].sort((left, right) => left.newStart - right.newStart);
  for (let index = 0; index < spec.deltas.length; index += 1) {
    const change = ordered[index];
    const expected = spec.deltas[index];
    if (
      change.newStart !== expected.line ||
      JSON.stringify(change.oldLines) !== JSON.stringify(expected.oldLines) ||
      JSON.stringify(change.newLines) !== JSON.stringify(expected.newLines)
    ) {
      throw new Error("page wiring mixed, renamed, or unexpected hunk");
    }
  }
  const newContents = ordered[0].newContents;
  const oldContents = ordered[0].oldContents;
  if (ordered.some((change) =>
    change.newContents !== newContents || change.oldContents !== oldContents)) {
    throw new Error("page wiring mixed source snapshots");
  }
  if (/Stryker\s+(disable|restore)/.test(newContents)) {
    throw new Error("page wiring mutation suppression is forbidden");
  }
  let reconstructedOld = newContents;
  for (const delta of [...spec.deltas].reverse()) {
    const next = `${delta.newLines.join("\n")}\n`;
    const previous = delta.oldLines.length === 0
      ? ""
      : `${delta.oldLines.join("\n")}\n`;
    if (reconstructedOld.split(next).length - 1 !== 1) {
      throw new Error("page wiring missing, duplicate, or extra delta");
    }
    reconstructedOld = reconstructedOld.replace(next, previous);
  }
  if (reconstructedOld !== oldContents) {
    throw new Error("page wiring mixed or extra edit");
  }

  const parsed = parseModule(source, newContents);
  exactNamedImports(parsed, spec.imports);
  const defaults = parsed.statements.filter((node) =>
    ts.isFunctionDeclaration(node) && node.modifiers?.some((modifier) =>
      modifier.kind === ts.SyntaxKind.DefaultKeyword));
  if (defaults.length !== 1 || !defaults[0].body) {
    throw new Error("page wiring must contain one default page function");
  }
  const elements = [];
  const visit = (node) => {
    if (
      ts.isJsxSelfClosingElement(node) &&
      ts.isIdentifier(node.tagName) && node.tagName.text === spec.component
    ) elements.push(node);
    ts.forEachChild(node, visit);
  };
  visit(defaults[0].body);
  if (elements.length !== 1) {
    throw new Error(`page wiring must contain one ${spec.component}`);
  }
  const element = elements[0];
  if (source.includes("/cupos/")) {
    const declarations = [];
    const findLabels = (node) => {
      if (ts.isVariableDeclaration(node) && ts.isIdentifier(node.name) &&
          node.name.text === "labels") declarations.push(node);
      ts.forEachChild(node, findLabels);
    };
    findLabels(defaults[0].body);
    const initializer = declarations[0]?.initializer;
    if (
      declarations.length !== 1 || !initializer || !ts.isCallExpression(initializer) ||
      !ts.isIdentifier(initializer.expression) ||
      initializer.expression.text !== "createPoolCardsLabels" ||
      initializer.arguments.length !== 1 || !ts.isIdentifier(initializer.arguments[0]) ||
      initializer.arguments[0].text !== "t"
    ) throw new Error("page wiring wrong translator call or assigned identifier");
    const labels = jsxAttribute(element, "labels");
    const items = jsxAttribute(element, "items");
    if (!ts.isIdentifier(labels) || labels.text !== "labels" ||
        !ts.isIdentifier(items) || items.text !== "items") {
      throw new Error("page wiring wrong PoolCards labels or items prop");
    }
  } else {
    const items = jsxAttribute(element, "items");
    const labels = jsxAttribute(element, "labels");
    const itemsText = items.getText(parsed);
    const labelsText = labels.getText(parsed);
    if (itemsText !== "blocked.items.map(toBlockedRequestItem)") {
      throw new Error("page wiring wrong request adapter or items prop");
    }
    if (labelsText !== "createBlockedRequestsLabels(t)") {
      throw new Error("page wiring wrong translator argument or labels prop");
    }
  }
  return {
    faultIds: spec.faultIds,
    ranges: ordered.map((change) =>
      `${change.source}:${change.newStart}-${change.newStart + change.newLines.length - 1}`),
    reason: "verification-only:page-wiring-bundle",
    source,
  };
}

const EXACT_FRAMEWORK_ADAPTERS = {
  "apps/web/src/app/(authenticated)/organizaciones/page.tsx": {
    sha256: "23f45735460082b1f28e52da675d060d2996fbfe566ac27db6db60d75e6f99fc",
  },
  "apps/web/src/app/(authenticated)/organizaciones/[vendorAccountId]/page.tsx": {
    sha256: "5394f1abbd72a39d45581fce4f41a4884d12cb1678b20512deddf025c11cfcc9",
  },
};

const EXACT_FRAMEWORK_ADAPTER_SOURCES = new Set(Object.keys(EXACT_FRAMEWORK_ADAPTERS));

/**
 * Audit the two Next.js composition roots whose remaining code solely invokes
 * framework/application seams. Business decisions live in scored loaders; the
 * detail root may only dispatch the already-scored `not-found` outcome.
 */
export function classifyExactFrameworkAdapter(source, contents, requestedRanges = []) {
  const spec = EXACT_FRAMEWORK_ADAPTERS[source];
  if (!spec) throw new Error("exact framework adapter wrong scope");
  if (/Stryker\s+(disable|restore)/.test(contents)) {
    throw new Error("exact framework adapter mutation suppression is forbidden");
  }
  if (sha256(contents) !== spec.sha256) throw new Error("exact framework adapter changed");
  for (const target of requestedRanges) {
    const range = rangeParts(target);
    if (range.source !== source || range.start < 1 || range.end > lineCount(contents)) {
      throw new Error("exact framework adapter range escapes source");
    }
  }
  return {
    ranges: requestedRanges.map((target) => ({ target, reason: "exact-source-hash" })),
    reason: "verification-only:exact-framework-adapter",
    source,
    verifiedMutationRanges: [...requestedRanges],
  };
}

export function partitionExactFrameworkAdapterTargets(targets, sourceContents) {
  const adapter = targets.filter((target) =>
    EXACT_FRAMEWORK_ADAPTER_SOURCES.has(rangeParts(target).source));
  for (const source of mutationSourceFiles(adapter)) {
    classifyExactFrameworkAdapter(
      source,
      sourceContents(source),
      adapter.filter((target) => rangeParts(target).source === source),
    );
  }
  return { adapter, routed: targets.filter((target) => !adapter.includes(target)) };
}

export function requireNonzeroMutationReport(report, shardId) {
  const mutants = mutationReportMutants(report);
  if (mutants.length === 0) {
    throw new Error(`scored mutation shard ${shardId} instrumented zero mutants`);
  }
  const testable = mutants.filter((mutant) => mutant.status !== "Ignored");
  if (testable.length === 0) {
    throw new Error(`scored mutation shard ${shardId} has zero testable mutants`);
  }
  return testable.length;
}

export function validateScoredMutationReport(report, breakThreshold, shardId) {
  const mutants = mutationReportMutants(report);
  requireNonzeroMutationReport(report, shardId);
  const terminal = new Set([
    "Killed", "Survived", "NoCoverage", "CompileError", "RuntimeError", "Timeout", "Ignored",
  ]);
  for (const mutant of mutants) {
    if (!terminal.has(mutant.status)) {
      throw new Error(`non-terminal or unknown mutant status in ${shardId}`);
    }
  }
  const valid = mutants.filter((mutant) =>
    ["Killed", "Timeout", "Survived", "NoCoverage"].includes(mutant.status));
  if (valid.length === 0) throw new Error(`scored mutation shard ${shardId} has zero valid mutants`);
  const detected = valid.filter((mutant) => ["Killed", "Timeout"].includes(mutant.status)).length;
  const score = (detected / valid.length) * 100;
  if (!Number.isFinite(breakThreshold) || breakThreshold < 0 || breakThreshold > 100) {
    throw new Error(`invalid mutation break threshold for ${shardId}`);
  }
  if (score < breakThreshold) {
    throw new Error(`mutation score ${score.toFixed(2)} is below break threshold ${breakThreshold}: ${shardId}`);
  }
  return score;
}

export function requireNonzeroStaticShard(kind, mutantCount, shardId) {
  if (SCORED_STATIC_KINDS.has(kind) && mutantCount === 0) {
    throw new Error(`scored mutation shard ${shardId} instrumented zero mutants`);
  }
}

function mutationReportMutants(report) {
  return report?.files && typeof report.files === "object"
    ? Object.values(report.files).flatMap((file) =>
        Array.isArray(file?.mutants) ? file.mutants : [])
    : [];
}

export function verificationAuditsForReport(
  report,
  shard,
  allHunks,
  classify = classifyVerificationOnlyHunk,
) {
  if (mutationReportMutants(report).length > 0) {
    throw new Error(`nonzero mutation shard ${shard.id} cannot downgrade to verification-only`);
  }
  if (shard.sources.includes(POOL_PROJECTION_SOURCE)) {
    if (shard.sources.length !== 1) {
      throw new Error("database projection bundle cannot share a verification-only shard");
    }
    const audit = classifyPoolSnapshotProjectionBundle(
      allHunks.filter((change) => change.source === POOL_PROJECTION_SOURCE),
    );
    if (
      JSON.stringify([...audit.ranges].sort()) !==
      JSON.stringify([...shard.mutate].sort())
    ) {
      throw new Error("database projection incomplete or extra mutation range set");
    }
    return [audit];
  }
  const vendorPageSources = shard.sources.filter((source) =>
    EXACT_FRAMEWORK_ADAPTER_SOURCES.has(source));
  if (vendorPageSources.length > 0) {
    if (vendorPageSources.length !== shard.sources.length) {
      throw new Error("exact framework adapter cannot share a verification-only shard");
    }
    return vendorPageSources.map((source) => classifyExactFrameworkAdapter(
      source,
      readFileSync(source, "utf8"),
      shard.mutate.filter((range) => rangeParts(range).source === source),
    ));
  }
  const pageSources = shard.sources.filter((source) => PAGE_WIRING_SOURCES.has(source));
  if (pageSources.length > 0) {
    if (shard.sources.length !== 1 || pageSources.length !== 1) {
      throw new Error("page wiring bundle cannot share a verification-only shard");
    }
    const audit = classifyPageWiringBundle(
      allHunks.filter((change) => change.source === pageSources[0]),
    );
    if (
      JSON.stringify([...audit.ranges].sort()) !==
      JSON.stringify([...shard.mutate].sort())
    ) throw new Error("page wiring incomplete or extra mutation range set");
    return [audit];
  }
  return shard.mutate.map((range) => {
    const change = allHunks.find((candidate) =>
      `${candidate.source}:${candidate.newStart}-${candidate.newStart + candidate.newLines.length - 1}` === range);
    if (!change) throw new Error(`no exact diff hunk for zero-mutant range: ${range}`);
    return classify(change);
  });
}

export function readFreshMutationReport(
  reportPath,
  startedAt,
  fileStat = statSync,
  fileRead = (path) => readFileSync(path, "utf8"),
) {
  let metadata;
  try {
    metadata = fileStat(reportPath);
  } catch {
    throw new Error(`missing mutation report: ${reportPath}`);
  }
  if (metadata.mtimeMs < startedAt) {
    throw new Error(`stale mutation report: ${reportPath}`);
  }
  try {
    return JSON.parse(fileRead(reportPath));
  } catch {
    throw new Error(`malformed mutation report: ${reportPath}`);
  }
}

export function controlledChildEnvironment(environment, runtimeProfile = {}) {
  const allowed = [
    "PATH", "HOME", "USER", "LOGNAME", "SHELL", "TMPDIR", "TMP", "TEMP",
    "LANG", "LC_ALL", "LC_MESSAGES", "TZ", "MIGRATIONS_DIR", "ECUADOR_HOLIDAYS",
  ];
  if (typeof environment.ECUADOR_HOLIDAYS === "string") {
    const holidays = environment.ECUADOR_HOLIDAYS.trim() === ""
      ? [] : environment.ECUADOR_HOLIDAYS.split(",").map((value) => value.trim());
    if (holidays.some((value) => {
      if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return true;
      const date = new Date(`${value}T00:00:00.000Z`);
      return Number.isNaN(date.valueOf()) || date.toISOString().slice(0, 10) !== value;
    })) throw new Error("ECUADOR_HOLIDAYS must be empty or a comma-separated ISO date list");
    environment = { ...environment, ECUADOR_HOLIDAYS: holidays.join(",") };
  }
  if (runtimeProfile.databaseDriver === "postgres") {
    const harnesses = String(runtimeProfile.databaseHarness ?? "default").split("-");
    for (const harness of harnesses) {
      if (harness === "default") allowed.push("DATABASE_URL", "DATABASE_ADMIN_URL");
      else {
        const prefix = harness.toUpperCase();
        allowed.push(
          `${prefix}_MUTATION_DATABASE_URL`,
          `${prefix}_MUTATION_DATABASE_ADMIN_URL`,
        );
      }
    }
    allowed.push("DB_DRIVER");
  }
  return Object.fromEntries(allowed
    .filter((key) => typeof environment[key] === "string")
    .map((key) => [key, environment[key]]));
}

export async function createDatabaseShardSandbox(
  environment,
  shardId,
  pgModule,
  { cleanupAttempts = 3 } = {},
) {
  const ownerUrl = environment.DATABASE_ADMIN_URL ?? environment.US017_MUTATION_DATABASE_ADMIN_URL;
  const appUrl = environment.DATABASE_URL ?? environment.US017_MUTATION_DATABASE_URL;
  if (!ownerUrl || !appUrl) throw new Error("database shard sandbox requires owner and app URLs");
  const template = new URL(ownerUrl).pathname.slice(1);
  if (!/^[a-z0-9_]+$/.test(template)) throw new Error("database shard template name is invalid");
  const slug = shardId.replace(/[^a-z0-9]/gi, "_").slice(0, 40).toLowerCase();
  const databaseName = `ledger_mutation_${slug}_${randomUUID().replaceAll("-", "")}`;
  const maintenanceUrl = new URL(ownerUrl);
  maintenanceUrl.pathname = "/postgres";
  const Client = pgModule.default?.Client ?? pgModule.Client;
  const maintenance = new Client({ connectionString: maintenanceUrl.toString() });
  await maintenance.connect();
  try {
    await maintenance.query(
      `CREATE DATABASE "${databaseName}" WITH TEMPLATE "${template}" OWNER ledger_owner`,
    );
  } finally {
    await maintenance.end();
  }
  const sandboxUrl = (source) => {
    const url = new URL(source);
    url.pathname = `/${databaseName}`;
    return url.toString();
  };
  const sandboxEnvironment = { ...environment };
  for (const key of Object.keys(sandboxEnvironment)) {
    if (key === "DATABASE_ADMIN_URL" || /^US\d+_MUTATION_DATABASE_ADMIN_URL$/.test(key)) {
      sandboxEnvironment[key] = sandboxUrl(ownerUrl);
    } else if (key === "DATABASE_URL" || /^US\d+_MUTATION_DATABASE_URL$/.test(key)) {
      sandboxEnvironment[key] = sandboxUrl(appUrl);
    }
  }
  if (!Number.isInteger(cleanupAttempts) || cleanupAttempts < 1) {
    throw new Error("database sandbox cleanupAttempts must be a positive integer");
  }
  let cleaned = false;
  let cleanupPromise = null;
  const cleanupOnce = async () => {
    const client = new Client({ connectionString: maintenanceUrl.toString() });
    await client.connect();
    try {
      await client.query(
        "SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname = $1 AND pid <> pg_backend_pid()",
        [databaseName],
      );
      await client.query(`DROP DATABASE IF EXISTS "${databaseName}"`);
    } finally {
      await client.end();
    }
  };
  return {
    databaseName,
    environment: sandboxEnvironment,
    async cleanup() {
      if (cleaned) return;
      if (cleanupPromise) return cleanupPromise;
      cleanupPromise = (async () => {
        let lastError;
        for (let attempt = 1; attempt <= cleanupAttempts; attempt += 1) {
          try {
            await cleanupOnce();
            cleaned = true;
            return;
          } catch (error) {
            lastError = error;
          }
        }
        throw new Error(
          `database sandbox cleanup exhausted ${cleanupAttempts} attempt(s) for ${databaseName}`,
          { cause: lastError },
        );
      })();
      try {
        return await cleanupPromise;
      } finally {
        if (!cleaned) cleanupPromise = null;
      }
    },
  };
}

export async function exitAfterDatabaseCleanup({
  cleanup,
  exit,
  interruptedExitCode,
  reportFailure,
}) {
  try {
    await cleanup();
  } catch (error) {
    reportFailure(error.message);
    exit(1);
    return;
  }
  exit(interruptedExitCode);
}

export function runVerificationCommands(commands, run = spawnSync, environment = {}) {
  if (commands.length === 0) throw new Error("verification-only result has no commands");
  for (const [command, args] of commands) {
    const result = run(command, args, { stdio: "inherit", env: environment });
    if (result.status !== 0) {
      throw new Error(`verification command failed: ${command} ${args.join(" ")}`);
    }
  }
  return commands.length;
}

export function projectionEvidencePathForShard(shard) {
  return shard.sources.includes(POOL_PROJECTION_SOURCE)
    ? join(
        GENERATED_SHARD_DIR,
        shard.jsonReportPath
          ? `${basename(shard.jsonReportPath, ".json")}-projection.json`
          : `${shard.id}-${(shard.evidenceKey ?? shard.provenance?.runHash).slice(0, 12)}-projection.json`,
      )
    : undefined;
}

export function verificationCommandsForSources(sources, testFiles, context = {}) {
  const commands = [];
  if (sources.includes(POOL_PROJECTION_SOURCE)) {
    if (!context.evidencePath) {
      throw new Error("database projection verification requires an evidence path");
    }
    commands.push([
      "node",
      ["scripts/verify-pool-snapshot-projection.mjs", context.evidencePath],
    ]);
  }
  if (sources.some((source) => PAGE_WIRING_SOURCES.has(source))) {
    if (sources.length !== 1) {
      throw new Error("page wiring verification must be file-specific");
    }
    commands.push([
      "./apps/web/node_modules/.bin/vitest",
      ["run", "--config", "vitest.mutation.config.mjs", ...testFiles],
    ]);
    commands.push(["pnpm", ["--filter", "smp-web", "type-check"]]);
    commands.push(["pnpm", ["--filter", "smp-web", "build"]]);
  }
  if (sources.some((source) => EXACT_FRAMEWORK_ADAPTER_SOURCES.has(source))) {
    if (!sources.every((source) => EXACT_FRAMEWORK_ADAPTER_SOURCES.has(source))) {
      throw new Error("exact framework adapter verification must be isolated");
    }
    commands.push([
      "./apps/web/node_modules/.bin/vitest",
      ["run", "--config", "vitest.mutation.config.mjs", ...testFiles],
    ]);
    commands.push(["pnpm", ["--filter", "smp-web", "type-check"]]);
  }
  if (sources.some((source) => source.startsWith("packages/connectors/"))) {
    commands.push(["node", ["--eval", 'require("node:fs").rmSync("packages/connectors/dist/module-wiring", { recursive: true, force: true })']]);
    commands.push(["pnpm", [
      "--filter", "@smp/connectors", "exec", "tsc",
      "--outDir", "dist/module-wiring", "--noEmit", "false",
      "--declaration", "false", "--composite", "false",
    ]]);
    commands.push(["node", ["--input-type=module", "--eval", [
      'const root = "./packages/connectors/dist/module-wiring/";',
      'const publicApi = await import(`${root}index.js`);',
      'const modules = await Promise.all(["contracts.js", "dispatch.js", "action-planner.js"].map((file) => import(`${root}${file}`)));',
      'const expected = new Map(); for (const module of modules) for (const name of Object.keys(module)) {',
      '  if (expected.has(name) && expected.get(name) !== module[name]) throw new Error(`conflicting connector export: ${name}`);',
      '  expected.set(name, module[name]);',
      '}',
      'if (JSON.stringify(Object.keys(publicApi).sort()) !== JSON.stringify([...expected.keys()].sort()))',
      '  throw new Error("connector public exports differ from exact module union");',
      'for (const [name, value] of expected) if (publicApi[name] !== value) throw new Error(`connector export identity mismatch: ${name}`);',
      'try { await import("./packages/connectors/dist/module-wiring/contracts"); throw new Error("extensionless negative control resolved"); }',
      'catch (error) { if (error.code !== "ERR_MODULE_NOT_FOUND") throw error; }',
    ].join(" ")]]);
  }
  if (sources.some((source) => source.startsWith("packages/contracts/"))) {
    commands.push(["pnpm", ["--filter", "@smp/contracts", "build"]]);
    commands.push(["node", ["--input-type=module", "--eval", [
      'import { readFileSync } from "node:fs";',
      'import { verifyContractsBarrelSource } from "./scripts/mutation-scope.mjs";',
      'const source = readFileSync("packages/contracts/src/index.ts", "utf8");',
      'verifyContractsBarrelSource(source);',
      'for (const name of ["capacity", "identity-access"]) {',
      '  const declaration = `export * from "./${name}";`;',
      '  for (const wrong of [source.replace(`${declaration}\\n`, ""), source.replace(declaration, `export * from "./wrong-${name}";`)]) {',
      '    let rejected = false; try { verifyContractsBarrelSource(wrong); } catch { rejected = true; }',
      '    if (!rejected) throw new Error(`contracts barrel negative control did not fail: ${name}`);',
      '  }',
      '}',
    ].join(" ")]]);
  }
  if (
    !sources.includes(POOL_PROJECTION_SOURCE) &&
    !sources.some((source) => PAGE_WIRING_SOURCES.has(source))
  ) {
    commands.push([
      "./apps/web/node_modules/.bin/vitest",
      ["run", "--config", "vitest.mutation.config.mjs", ...testFiles],
    ]);
  }
  return commands;
}

export function verifyContractsBarrelSource(
  contents,
  fileExists = existsSync,
  source = "packages/contracts/src/index.ts",
) {
  const parsed = parseModule(source, contents);
  const expected = ["./capacity", "./identity-access"];
  const resolved = [];
  for (const specifier of expected) {
    const exports = moduleDeclarations(parsed).filter((node) =>
      ts.isExportDeclaration(node) && node.exportClause === undefined &&
      !node.isTypeOnly && node.moduleSpecifier.text === specifier);
    if (exports.length !== 1) {
      throw new Error(
        `contracts barrel must contain exactly one ${specifier} export; found ${exports.length}`,
      );
    }
    assertNoImportAttributes(exports[0]);
    resolved.push(relativeModuleTarget(source, specifier, fileExists));
  }
  return resolved;
}

function mutationTargets(base, sourceFiles) {
  if (sourceFiles.length === 0) return [];
  const mergeBase = mergeBaseFor(base);
  const patch = git([
    "-c", "core.quotepath=false", "diff", "--no-ext-diff", "--no-renames",
    "--unified=0", "--diff-filter=ACMR", mergeBase, "--", ...sourceFiles,
  ]);
  const untrackedPaths = new Set(
    git(["ls-files", "--others", "--exclude-standard"])
      .split("\n")
      .filter(Boolean),
  );
  const untracked = new Map(
    sourceFiles
      .filter((path) => untrackedPaths.has(path))
      .map((path) => [path, lineCount(readFileSync(path, "utf8"))]),
  );
  return mutationTargetsFromPatch(patch, untracked);
}

function mutationHunks(base, sourceFiles) {
  if (sourceFiles.length === 0) return [];
  const mergeBase = mergeBaseFor(base);
  const patch = git([
    "-c", "core.quotepath=false", "diff", "--no-ext-diff", "--no-renames",
    "--unified=0", "--diff-filter=ACMR", mergeBase, "--", ...sourceFiles,
  ]);
  const cache = new Map();
  const contentsForSource = (source) => {
    if (!cache.has(source)) {
      let oldContents = "";
      try {
        oldContents = execFileSync("git", ["show", `${mergeBase}:${source}`], {
          encoding: "utf8", stdio: ["ignore", "pipe", "ignore"],
        });
      } catch { /* added file */ }
      cache.set(source, { oldContents, newContents: readFileSync(source, "utf8") });
    }
    return cache.get(source);
  };
  return mutationHunksFromPatch(patch, contentsForSource);
}

