// Static source/schema enforcement tests inspect an uninstrumented application
// tree. Stryker necessarily rewrites that tree before its dry run, so these
// scanners reject the mutation sandbox itself before any mutant can run. They
// remain mandatory in the normal lint/check pipeline.
const MUTATION_INCOMPATIBLE_TESTS = new Set([
  "apps/web/src/modules/audit/audited-actions-enforcement.test.ts",
  "packages/db/src/migration-release.integration.test.ts",
  "packages/db/src/schema-parity.test.ts",
]);

export function mutationCompatibleTestFiles(testFiles) {
  return testFiles.filter((file) => !MUTATION_INCOMPATIBLE_TESTS.has(file));
}

function testsForSource(source, fileExists, directRoutes) {
  const responsible = new Set();
  const stem = source.replace(/\.(ts|tsx)$/, "");
  for (const suffix of ADJACENT_TEST_SUFFIXES) {
    const candidate = `${stem}${suffix}`;
    if (fileExists(candidate)) responsible.add(candidate);
  }
  for (const candidate of directRoutes[source] ?? []) {
    if (fileExists(candidate)) responsible.add(candidate);
  }
  return [...responsible].sort();
}

export function routedTestFiles(changed, mutate, fileExists = existsSync, directRoutes = DIRECT_TEST_ROUTES) {
  const routed = new Set(changed.filter((file) => TEST_FILE.test(file)));
  for (const source of mutate) {
    for (const candidate of testsForSource(source, fileExists, directRoutes)) routed.add(candidate);
  }
  return [...routed].sort();
}

export function requireRoutedTestFiles(changed, mutate, fileExists = existsSync, directRoutes = DIRECT_TEST_ROUTES) {
  for (const source of mutate) {
    if (testsForSource(source, fileExists, directRoutes).length === 0) {
      throw new Error(`mutatable source has no responsible Vitest test route: ${source}`);
    }
  }
  return routedTestFiles(changed, mutate, fileExists, directRoutes);
}

function defaultToolVersions() {
  const packageVersion = (url) => JSON.parse(readFileSync(url, "utf8")).version;
  const rootPackage = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8"));
  return {
    node: process.versions.node,
    pnpm: String(rootPackage.packageManager ?? "pnpm@0.0.0").replace(/^pnpm@/, ""),
    stryker: packageVersion(new URL("../node_modules/@stryker-mutator/core/package.json", import.meta.url)),
    typescript: ts.version,
    vitest: packageVersion(new URL("../apps/web/node_modules/vitest/package.json", import.meta.url)),
  };
}

function localRuntimeProfile() {
  return {
    arch: process.arch,
    locale: Intl.DateTimeFormat().resolvedOptions().locale,
    platform: process.platform,
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
  };
}

export function databaseHarnessIdentity(shard, environment = process.env) {
  const adminKeys = Object.keys(environment)
    .filter((key) => /^US\d+_MUTATION_DATABASE_ADMIN_URL$/.test(key) && environment[key])
    .sort();
  const directlyReferenced = adminKeys.filter((key) => {
    const appKey = key.replace("_ADMIN_URL", "_URL");
    return shard?.testFiles.some((test) => existsSync(test)
      && [key, appKey].some((candidate) => readFileSync(test, "utf8").includes(candidate)));
  });
  const selected = directlyReferenced.length === 1
    ? directlyReferenced[0]
    : adminKeys.length === 1 ? adminKeys[0] : null;
  if (directlyReferenced.length > 1 || (!selected && adminKeys.length > 1)) {
    throw new Error("runtime-profile-unavailable");
  }
  return selected ?? "DATABASE_ADMIN_URL";
}

async function defaultRuntimeProfile({ shard, environment = process.env } = {}) {
  const local = localRuntimeProfile();
  if (!shard || !isDatabaseBacked(shard)) return local;
  const [{ verifyMigratedSchema }, { committedMigrations }, pgModule] = await Promise.all([
    import("../packages/db/scripts/verify-schema.mjs"),
    import("../packages/db/scripts/apply-migrations.mjs"),
    import("../packages/db/node_modules/pg/esm/index.mjs"),
  ]);
  const databaseHarness = databaseHarnessIdentity(shard, environment);
  const databaseAdminUrl = environment[databaseHarness];
  const databaseUrlKey = databaseHarness === "DATABASE_ADMIN_URL"
    ? "DATABASE_URL" : databaseHarness.replace("_ADMIN_URL", "_URL");
  const applicationUrl = environment[databaseUrlKey];
  if (!databaseAdminUrl || !applicationUrl) throw new Error("runtime-profile-unavailable");
  const verification = await verifyMigratedSchema({ databaseAdminUrl, applicationUrl });
  const migrations = await committedMigrations(environment.MIGRATIONS_DIR);
  const client = new pgModule.default.Client({
    connectionString: databaseAdminUrl,
    application_name: "ledger-mutation-runtime-profile",
  });
  await client.connect();
  let databaseServerVersion;
  try {
    const version = await client.query("SHOW server_version");
    databaseServerVersion = /\d+(?:\.\d+){0,3}/.exec(
      version.rows[0]?.server_version ?? "",
    )?.[0];
  } finally {
    await client.end();
  }
  const equivalentHarnesses = [
    ...(environment.DATABASE_ADMIN_URL === databaseAdminUrl
        && environment.DATABASE_URL === applicationUrl ? ["default"] : []),
    ...Object.keys(environment)
      .filter((key) => /^US\d+_MUTATION_DATABASE_ADMIN_URL$/.test(key)
        && environment[key] === databaseAdminUrl
        && environment[key.replace("_ADMIN_URL", "_URL")] === applicationUrl)
      .map((key) => key.replace(/_MUTATION_DATABASE_ADMIN_URL$/, "").toLowerCase()),
  ].sort();
  return {
    ...local,
    databaseDriver: "postgres",
    databaseHarness: [...new Set(equivalentHarnesses)].join("-"),
    databaseServerVersion,
    schemaFingerprint: sha256(JSON.stringify({ migrations, verification })),
  };
}

export function isDatabaseBacked(shard) {
  return shard.sources.some((source) => source.startsWith("packages/db/"))
    || shard.sources.some((source) => existsSync(source)
      && /process\.env\.(?:DATABASE_URL|DATABASE_ADMIN_URL)/.test(readFileSync(source, "utf8")))
    || shard.testFiles.some((test) =>
      test.startsWith("packages/db/")
      || (/\.integration\.test\.[cm]?[jt]sx?$/.test(test) && !/\.pact\.test\./.test(test)));
}

function sanitizedRuntimeProfile(profile, databaseBacked) {
  const allowed = databaseBacked
    ? ["platform", "arch", "locale", "timezone", "databaseDriver", "databaseHarness", "databaseServerVersion", "schemaFingerprint"]
    : ["platform", "arch", "locale", "timezone"];
  if (!profile || typeof profile !== "object" || Array.isArray(profile)) {
    throw new Error("runtime-profile-unavailable");
  }
  const result = Object.fromEntries(allowed.map((key) => [key, profile[key]]));
  if (Object.values(result).some((value) => typeof value !== "string" || value.length === 0)) {
    throw new Error("runtime-profile-unavailable");
  }
  if (databaseBacked && !/^[a-f0-9]{64}$/.test(result.schemaFingerprint)) {
    throw new Error("runtime-profile-unavailable");
  }
  return result;
}

export function createCampaignRuntimeProfileResolver(provider, environment = process.env) {
  const databaseProfiles = new Map();
  return async (shard) => {
    if (!isDatabaseBacked(shard)) return Object.freeze({ ...(await provider({ shard, environment })) });
    let identity;
    try {
      identity = databaseHarnessIdentity(shard, environment);
    } catch {
      identity = "ambiguous";
    }
    if (!databaseProfiles.has(identity)) {
      databaseProfiles.set(identity, Promise.resolve()
        .then(() => provider({ shard, environment }))
        .then((profile) => ({
          ...profile,
          databaseHarness: profile?.databaseHarness
            ?? (identity === "DATABASE_ADMIN_URL" ? "default" : identity
              .replace(/_MUTATION_DATABASE_ADMIN_URL$/, "").toLowerCase()),
        })));
    }
    const profile = await databaseProfiles.get(identity);
    return Object.freeze({ ...profile });
  };
}

function rehydrateCachedReport(cachedPath, destination, shard) {
  const report = JSON.parse(readFileSync(cachedPath, "utf8"));
  if (report.config?.mutationIdentity !== contentHash(JSON.stringify(shard.mutate))) {
    throw new Error(`cached mutation config identity mismatch: ${shard.id}`);
  }
  for (const [source, file] of Object.entries(report.files ?? {})) {
    const sourceBytes = readFileSync(source, "utf8");
    if (file.sourceHash !== contentHash(sourceBytes)) {
      throw new Error(`cached mutation source identity mismatch: ${source}`);
    }
    file.source = sourceBytes;
    delete file.sourceHash;
  }
  report.config = {
    mutate: shard.mutate,
    configFile: shard.configPath,
    jsonReporter: { ...report.config?.jsonReporter, fileName: shard.jsonReportPath },
  };
  mkdirSync(dirname(destination), { recursive: true });
  writeFileSync(destination, `${JSON.stringify(report)}\n`, "utf8");
}

export async function runMutationScope(options = {}) {
  const previousCwd = process.cwd();
  const previousEnvironment = {};
  const signalHandlers = [];
  const activeDatabaseSandboxes = new Set();
  const signalProcess = options.signalProcess ?? process;
  const cleanupFailureReporter = options.cleanupFailureReporter
    ?? ((message) => console.error(`mutation-scope: ${message}`));
  let signalShutdownPromise = null;
  let activeShardProcess = null;
  const cleanupDatabaseSandbox = async (record) => {
    if (record.cleanupPromise) return record.cleanupPromise;
    record.cleanupPromise = (async () => {
      const sandbox = await record.promise;
      let lastError;
      for (let attempt = 1; attempt <= 3; attempt += 1) {
        try {
          await sandbox.cleanup();
          activeDatabaseSandboxes.delete(record);
          return;
        } catch (error) {
          lastError = error;
        }
      }
      throw new Error(
        `database sandbox cleanup exhausted 3 campaign attempt(s) for ${sandbox.databaseName ?? "unknown"}`,
        { cause: lastError },
      );
    })();
    try {
      return await record.cleanupPromise;
    } finally {
      if (activeDatabaseSandboxes.has(record)) record.cleanupPromise = null;
    }
  };
  const cleanupAllDatabaseSandboxes = async () => {
    const results = await Promise.allSettled(
      [...activeDatabaseSandboxes].map(cleanupDatabaseSandbox),
    );
    const failures = results
      .filter((result) => result.status === "rejected")
      .map((result) => result.reason);
    if (failures.length > 0) {
      throw new AggregateError(failures, "database sandbox cleanup failed");
    }
  };
  const environment = options.env ?? process.env;
  if (options.cwd) process.chdir(options.cwd);
  for (const key of ["MUTATION_BASE", "MUTATION_CACHE", "MUTATION_SCOPE_DRY"]) {
    previousEnvironment[key] = process.env[key];
    if (environment[key] === undefined) delete process.env[key];
    else process.env[key] = environment[key];
  }
  try {
  const baseRef = resolveBase();
  const resolvedBase = mergeBaseFor(baseRef);
  const head = git(["rev-parse", "HEAD"]);
  const changed = changedFiles(baseRef);
  const changedSources = mutatable(changed);
  const allMutate = mutationTargets(baseRef, changedSources);
  const allHunks = mutationHunks(baseRef, changedSources);
  const worktreeHash = contentHash(changed.map((path) =>
    `${path}\0${existsSync(path) ? readFileSync(path, "utf8") : "<deleted>"}`).join("\0"));
  const toolVersions = options.toolVersions ?? defaultToolVersions();
  const schemaStaticMutate = allMutate.filter((target) =>
    target.replace(/:\d+-\d+$/, "") === SCHEMA_STATIC_SOURCE);
  const vitestConfigStaticMutate = allMutate.filter((target) =>
    target.replace(/:\d+-\d+$/, "") === VITEST_CONFIG_STATIC_SOURCE);
  if (vitestConfigStaticMutate.length > 0 && (
    vitestConfigStaticMutate.length !== 1 ||
    vitestConfigStaticMutate[0] !== VITEST_CONFIG_STATIC_RANGE
  )) {
    fail(
      `vitest config static shard must contain exactly ${VITEST_CONFIG_STATIC_RANGE}`,
      `found: ${vitestConfigStaticMutate.join(", ")}`,
    );
  }
  const staticMutate = new Set([...schemaStaticMutate, ...vitestConfigStaticMutate]);
  const adapterPartition = partitionExactFrameworkAdapterTargets(
    allMutate,
    (source) => readFileSync(source, "utf8"),
  );
  const vendorAccountPageAdapterMutate = adapterPartition.adapter;
  const vendorAccountPageAdapterSources = mutationSourceFiles(vendorAccountPageAdapterMutate);
  const routedMutate = adapterPartition.routed.filter((target) => !staticMutate.has(target));

  console.log(
    `mutation-scope: base=${resolvedBase} changed=${changed.length} ` +
      `mutatable=${mutationSourceFiles(allMutate).length} ranges=${allMutate.length} ` +
      `schemaStaticRanges=${schemaStaticMutate.length}`,
  );

  if (allMutate.length === 0) {
    console.log("mutation-scope: no mutatable files in diff — nothing to mutate");
    return { manifest: null, performance: null };
  }

  let baseConf = {};
  try {
    baseConf = JSON.parse(readFileSync(BASE_CONFIG, "utf8"));
  } catch {
    fail(`cannot read ${BASE_CONFIG}`, "run from the repository root");
  }

  let routedGroups;
  try {
    routedGroups = groupRoutedMutationTargets(routedMutate, (source) =>
      mutationCompatibleTestFiles(testsForSource(source, existsSync, DIRECT_TEST_ROUTES)));
  } catch (error) {
    fail(error.message, "add a conventional adjacent test or an explicit accountable route");
  }

  const shardSpecs = routedGroups.map((group) => ({ kind: "vitest", ...group }));
  if (vendorAccountPageAdapterMutate.length > 0) {
    const testFiles = [...new Set(vendorAccountPageAdapterSources.flatMap((source) =>
      mutationCompatibleTestFiles(testsForSource(source, existsSync, DIRECT_TEST_ROUTES))))].sort();
    if (testFiles.length === 0) {
      fail("exact framework adapter has no accountable focused tests");
    }
    shardSpecs.push({
      kind: EXACT_FRAMEWORK_ADAPTER_KIND,
      mutate: vendorAccountPageAdapterMutate,
      sources: vendorAccountPageAdapterSources,
      testFiles,
    });
  }
  if (schemaStaticMutate.length > 0) {
    requireRoutedTestFiles(
      changed,
      mutationSourceFiles(schemaStaticMutate),
    );
    shardSpecs.push({
      kind: "schema-static",
      mutate: schemaStaticMutate,
      sources: [SCHEMA_STATIC_SOURCE],
      testFiles: ["packages/db/src/schema.test.ts"],
    });
  }
  if (vitestConfigStaticMutate.length > 0) {
    requireRoutedTestFiles(
      changed,
      [VITEST_CONFIG_STATIC_SOURCE],
    );
    shardSpecs.push({
      kind: "vitest-config-static",
      mutate: vitestConfigStaticMutate,
      sources: [VITEST_CONFIG_STATIC_SOURCE],
      testFiles: ["apps/web/next.config.test.ts"],
    });
  }

  const {
    commandRunner: _commandRunner,
    htmlReporter: _htmlReporter,
    mutate: _baseMutate,
    tempDirName: _tempDirName,
    testFiles: _baseTestFiles,
    vitest: _baseVitest,
    ...sharedBaseConf
  } = baseConf;
  const runSuffix = process.env.MUTATION_SCOPE_DRY === "1"
    ? "dry"
    : (options.runId ?? `${process.pid}-${Date.now()}-${Math.random().toString(16).slice(2)}`);
  const shards = shardSpecs.map((spec) => {
    const digest = createHash("sha256")
      .update([spec.kind, ...spec.sources, ...spec.testFiles, ...spec.mutate].join("\n"))
      .digest("hex")
      .slice(0, 12);
    const id = `${spec.kind}-${digest}`;
    const configPath = join(GENERATED_SHARD_DIR, `${id}-${runSuffix}.json`);
    const tempDirName = join(".tmp", `stryker-${id}-${runSuffix}`);
    const contentHashes = Object.fromEntries(
      spec.sources.map((source) => [source, contentHash(readFileSync(source, "utf8"))]),
    );
    const reportPath = join("reports", "mutation", `${id}-${runSuffix}.html`);
    const jsonReportPath = join("reports", "mutation", `${id}-${runSuffix}.json`);
    const common = {
      ...sharedBaseConf,
      mutate: spec.mutate.map(strykerMutationTarget),
      coverageAnalysis: "off",
      concurrency: 1,
      maxTestRunnerReuse: 1,
      timeoutFactor: 2,
      tempDirName,
      htmlReporter: { fileName: reportPath },
      jsonReporter: { fileName: jsonReportPath },
      reporters: [...new Set([...(sharedBaseConf.reporters ?? []), "json"])],
      thresholds: {
        ...baseConf.thresholds,
        high: 80,
        break: 80,
      },
    };
    const config = SCORED_STATIC_KINDS.has(spec.kind)
      ? {
          ...common,
          testRunner: "command",
          commandRunner: {
            command: spec.kind === "schema-static"
              ? "./apps/web/node_modules/.bin/vitest run --root packages/db --config vitest.config.ts src/schema.test.ts"
              : "./apps/web/node_modules/.bin/vitest run --root apps/web --config vitest.static-contract.config.mjs next.config.test.ts",
          },
        }
      : {
          ...common,
          testRunner: "vitest",
          vitest: {
            ...baseConf.vitest,
            related: false,
            configFile: "vitest.mutation.config.mjs",
          },
          testFiles: spec.testFiles,
        };
    const configText = `${JSON.stringify(config, null, 2)}\n`;
    const configIdentity = normalizeMutationConfigIdentity(config);
    const configIdentityText = `${JSON.stringify(configIdentity, null, 2)}\n`;
    return {
      cacheDecision: "pending",
      classification: "pending",
      config,
      configHash: contentHash(configIdentityText),
      configPath,
      configText,
      contentHashes,
      dependencyHashes: {},
      durationMs: null,
      evidenceKey: null,
      id,
      kind: spec.kind,
      jsonReportPath,
      mutantCount: null,
      mutate: spec.mutate,
      priorDurationMs: null,
      reportHash: null,
      reportPath,
      result: "pending",
      sources: spec.sources,
      tempDirName,
      testFiles: spec.testFiles,
    };
  }).sort((left, right) => left.id.localeCompare(right.id));

  mkdirSync(GENERATED_SHARD_DIR, { recursive: true });
  for (const shard of shards) {
    writeFileSync(shard.configPath, shard.configText, "utf8");
  }
  const manifestFor = () => ({
    provenance: { base: resolvedBase, baseRef, head, worktreeHash },
    shards: shards.map(({ config, configText, ...shard }) => shard),
    toolVersions,
  });
  writeFileSync(
    GENERATED_MANIFEST,
    `${JSON.stringify(manifestFor(), null, 2)}\n`,
    "utf8",
  );
  console.log(`mutation-scope: wrote ${shards.length} shards + ${GENERATED_MANIFEST}`);

  if (process.env.MUTATION_SCOPE_DRY === "1") {
    console.log("mutation-scope: MUTATION_SCOPE_DRY=1 — not running Stryker");
    return { manifest: manifestFor(), performance: null };
  }

  const cacheMode = process.env.MUTATION_CACHE === "off" ? "bypass" : "enabled";
  const performanceRun = createPerformanceRun({
    provenance: {
      campaignKey: sha256(shards.map((shard) => `${shard.id}:${shard.configHash}`).join("\n")),
      head,
      base: resolvedBase,
      baseRef,
    },
    cacheMode,
    machine: options.machine ?? {
      os: `${os.type()} ${os.release()}`,
      arch: os.arch(), logicalCpuCount: os.cpus().length, memoryBytes: os.totalmem(), toolVersions,
    },
    ...(options.performanceOptions ?? {}),
  });
  const persist = () => {
    writeFileSync(GENERATED_MANIFEST, `${JSON.stringify(manifestFor(), null, 2)}\n`, "utf8");
    writePerformanceRecord(process.cwd(), performanceRun);
  };
  if (options.installSignalHandlers !== false) {
    for (const signal of ["SIGINT", "SIGTERM"]) {
      const handler = () => {
        signalShutdownPromise ??= (async () => {
          finishPerformanceRun(performanceRun, "interrupted");
          persist();
          if (activeShardProcess?.pid) {
            try {
              process.kill(-activeShardProcess.pid, signal);
            } catch (error) {
              if (error?.code !== "ESRCH") throw error;
            }
          }
          await exitAfterDatabaseCleanup({
            cleanup: cleanupAllDatabaseSandboxes,
            exit: (code) => signalProcess.exit(code),
            interruptedExitCode: signal === "SIGINT" ? 130 : 143,
            reportFailure: cleanupFailureReporter,
          });
        })();
        return signalShutdownPromise;
      };
      signalProcess.once(signal, handler);
      signalHandlers.push([signal, handler]);
    }
  }
  persist();
  try {
  options.beforeEvidence?.();
  if (signalShutdownPromise) {
    await signalShutdownPromise;
    return { manifest: manifestFor(), performance: performanceRun };
  }
  const gitAtRoot = (args, execOptions = {}) => execFileSync("git", args, {
    ...execOptions, encoding: "utf8",
  }).trim();
  const repositoryCacheRoot = cacheRoot(process.cwd(), gitAtRoot);
  const runtimeProfileProvider = options.runtimeProfileProvider ?? defaultRuntimeProfile;
  const resolveRuntimeProfile = createCampaignRuntimeProfileResolver(runtimeProfileProvider, environment);
  const executionContexts = new Map();
  for (const shard of shards) {
    let runtimeProfile;
    try {
      runtimeProfile = sanitizedRuntimeProfile(
        await resolveRuntimeProfile(shard),
        isDatabaseBacked(shard),
      );
    } catch {
      runtimeProfile = sanitizedRuntimeProfile(localRuntimeProfile(), false);
      shard.cacheDecision = "rejected";
      shard.reason = "runtime-profile-unavailable";
    }
    const commandList = verificationCommandsForSources(
      shard.sources,
      shard.testFiles,
      { evidencePath: "<projection-evidence>" },
    ).map(([command, args]) => [command, ...args]);
    const commandFiles = commandList.flatMap((command) => command)
      .filter((candidate) => typeof candidate === "string"
        && /\.(?:[cm]?[jt]sx?|json)$/.test(candidate)
        && candidate !== "scripts/verify-pool-snapshot-projection.mjs"
        && existsSync(candidate));
    const configurationFiles = [
      BASE_CONFIG,
      "vitest.mutation.config.mjs",
      "apps/web/vitest.static-contract.config.mjs",
      "packages/db/vitest.config.ts",
      ...(shard.sources.some((source) => PAGE_WIRING_SOURCES.has(source))
        ? ["apps/web/next.config.ts"] : []),
    ]
      .filter((file) => existsSync(file));
    const entryFiles = [...shard.sources, ...shard.testFiles, ...commandFiles]
      .filter((file) => existsSync(file));
    const executionInputs = collectExecutionInputs({
      root: process.cwd(),
      entryFiles,
      configurationFiles,
      staticFiles: [
        ...MUTATION_RUNNER_STATIC_INPUTS,
        ...(shard.sources.includes(POOL_PROJECTION_SOURCE)
          ? POOL_PROJECTION_STATIC_INPUTS : []),
      ].filter((file) => existsSync(file)),
      migrationRoots: isDatabaseBacked(shard) && existsSync("packages/db/src/migrations")
        ? ["packages/db/src/migrations"] : [],
      toolVersions,
      runtimeProfile,
      environment: controlledChildEnvironment({ ...process.env, ...environment }, runtimeProfile),
    });
    shard.dependencyHashes = executionInputs.hashes;
    if (!executionInputs.reusable && shard.cacheDecision !== "rejected") {
      shard.cacheDecision = "rejected";
      shard.reason = executionInputs.reasons[0]?.code ?? "dependency-profile-unavailable";
    }
    shard.evidenceKey = createEvidenceKey({
      shardKind: shard.kind,
      mutate: shard.mutate,
      sources: shard.sources,
      testFiles: shard.testFiles,
      config: normalizeMutationConfigIdentity(shard.config),
      dependencyHashes: shard.dependencyHashes,
      toolVersions,
      runtimeProfile,
      commandList,
    });
    executionContexts.set(shard.id, { commandList, executionInputs, runtimeProfile });
  }
  performanceRun.provenance.campaignKey = sha256(
    shards.map((shard) => shard.evidenceKey).sort().join("\n"),
  );
  persist();
  const executeShard = options.executeShard ?? (({ shard, environment: childEnvironment }) =>
    new Promise((resolveExecution, rejectExecution) => {
      const child = spawn("pnpm", ["exec", "stryker", "run", shard.configPath], {
        detached: true,
        stdio: "inherit",
        env: childEnvironment,
      });
      activeShardProcess = child;
      child.once("error", rejectExecution);
      child.once("close", (status, childSignal) => {
        if (activeShardProcess === child) activeShardProcess = null;
        const signalStatus = childSignal === "SIGINT" ? 130 : childSignal === "SIGTERM" ? 143 : 1;
        resolveExecution({ status: status ?? signalStatus });
      });
    }));
    for (const shard of shards) {
      const { commandList, executionInputs, runtimeProfile } = executionContexts.get(shard.id);
      console.log(`mutation-scope: running ${shard.id} (${shard.mutate.length} ranges)`);
      const performanceToken = startShard(performanceRun, {
        id: shard.id, evidenceKey: shard.evidenceKey, classification: "pending",
      });
      const startedAt = Date.now();
      let cached = null;
      if (cacheMode === "enabled" && shard.cacheDecision !== "rejected") {
        cached = readCacheEntry({
          root: repositoryCacheRoot,
          evidenceKey: shard.evidenceKey,
          validateArtifacts: (artifacts, entry) => {
            if (
              entry.evidenceKey !== shard.evidenceKey
              || entry.shardKind !== shard.kind
              || entry.result !== "passed"
              || !["scored", "verification-only"].includes(entry.classification)
              || canonicalJson(entry.toolVersions) !== canonicalJson(toolVersions)
              || canonicalJson(entry.runtimeProfile) !== canonicalJson(runtimeProfile)
              || canonicalJson(entry.dependencyHashes) !== canonicalJson(shard.dependencyHashes)
              || entry.commandIdentity !== sha256(canonicalJson(commandList))
            ) return false;
            const reportArtifact = artifacts["mutation-report.json"];
            if (!reportArtifact) return false;
            rehydrateCachedReport(reportArtifact, shard.jsonReportPath, shard);
            const projectionPath = projectionEvidencePathForShard(shard);
            if (projectionPath) {
              const projectionArtifact = artifacts["projection-evidence.json"];
              if (!projectionArtifact) return false;
              mkdirSync(dirname(projectionPath), { recursive: true });
              copyFileSync(projectionArtifact, projectionPath);
              validatePoolProjectionEvidence(
                JSON.parse(readFileSync(projectionPath, "utf8")),
                readFileSync(POOL_PROJECTION_SOURCE, "utf8"),
              );
            }
            const report = JSON.parse(readFileSync(shard.jsonReportPath, "utf8"));
            validateMutationReportIdentity(
              report, shard, readFileSync(shard.configPath, "utf8"),
              (source) => readFileSync(source, "utf8"),
            );
            const mutants = mutationReportMutants(report);
            if (mutants.length > 0) {
              if (entry.classification !== "scored") return false;
              validateScoredMutationReport(report, shard.config.thresholds.break, shard.id);
            } else {
              if (entry.classification !== "verification-only") return false;
              requireNonzeroStaticShard(shard.kind, mutants.length, shard.id);
              verificationAuditsForReport(report, shard, allHunks);
            }
            return true;
          },
        });
      }
      if (cached?.hit) {
        shard.classification = cached.entry.classification;
        const cachedReport = JSON.parse(readFileSync(shard.jsonReportPath, "utf8"));
        shard.mutantCount = mutationReportMutants(cachedReport).length;
        shard.reportHash = contentHash(readFileSync(shard.jsonReportPath));
        if (shard.classification === "verification-only") {
          const projectionPath = projectionEvidencePathForShard(shard);
          shard.result = {
            audits: verificationAuditsForReport(cachedReport, shard, allHunks),
            commands: commandList,
            ...(projectionPath
              ? { projectionEvidence: validatePoolProjectionEvidence(
                  JSON.parse(readFileSync(projectionPath, "utf8")),
                  readFileSync(POOL_PROJECTION_SOURCE, "utf8"),
                ) }
              : {}),
            tests: shard.testFiles,
          };
        } else {
          shard.result = "passed";
        }
        shard.cacheDecision = "reused";
        shard.priorDurationMs = cached.entry.durationMs ?? 0;
        const timing = finishShard(performanceRun, performanceToken, "reused", {
          classification: cached.entry.classification,
          result: "passed", priorDurationMs: shard.priorDurationMs,
        });
        shard.durationMs = timing.durationMs;
        persist();
        continue;
      }
      if (cached && !cached.hit && cached.reason !== "not-found") {
        shard.cacheDecision = "rejected";
        shard.reason = cached.reason;
        shard.priorDurationMs = cached.entry?.durationMs ?? null;
      }
      rmSync(shard.jsonReportPath, { force: true });
      rmSync(shard.reportPath, { force: true });
      let shardEnvironment = environment;
      let databaseSandbox = null;
      let databaseSandboxRecord = null;
      if (isDatabaseBacked(shard) && (!options.executeShard || options.databaseSandboxFactory)) {
        const factory = options.databaseSandboxFactory ?? (async (env, id) =>
          createDatabaseShardSandbox(env, id, await import("../packages/db/node_modules/pg/esm/index.mjs")));
        databaseSandboxRecord = {};
        activeDatabaseSandboxes.add(databaseSandboxRecord);
        databaseSandboxRecord.promise = Promise.resolve()
          .then(() => factory(environment, shard.id));
        try {
          databaseSandbox = await databaseSandboxRecord.promise;
        } catch (error) {
          activeDatabaseSandboxes.delete(databaseSandboxRecord);
          throw error;
        }
        shardEnvironment = databaseSandbox.environment;
      }
      if (signalShutdownPromise) {
        await signalShutdownPromise;
        return { manifest: manifestFor(), performance: performanceRun };
      }
      const childEnvironment = controlledChildEnvironment(shardEnvironment, runtimeProfile);
      let result;
      if (shard.kind === EXACT_FRAMEWORK_ADAPTER_KIND) {
        writeFileSync(shard.jsonReportPath, `${JSON.stringify({
          config: {
            configFile: shard.configPath,
            jsonReporter: { fileName: shard.jsonReportPath },
            mutate: shard.mutate,
          },
          files: {},
        })}\n`, "utf8");
        result = { status: 0 };
      } else {
        result = await executeShard({ shard, environment: childEnvironment });
      }
      if (signalShutdownPromise) {
        await signalShutdownPromise;
        return { manifest: manifestFor(), performance: performanceRun };
      }
      const report = readFreshMutationReport(shard.jsonReportPath, startedAt);
      validateMutationReportIdentity(
        report,
        shard,
        readFileSync(shard.configPath, "utf8"),
        (source) => readFileSync(source, "utf8"),
      );
      const mutants = mutationReportMutants(report);
      shard.mutantCount = mutants.length;
      shard.reportHash = contentHash(readFileSync(shard.jsonReportPath));
      if (mutants.length === 0) {
        if (result.status !== 0) {
          throw new Error(`zero-mutant shard ${shard.id} exited ${result.status}`);
        }
        requireNonzeroStaticShard(shard.kind, mutants.length, shard.id);
        const audits = verificationAuditsForReport(report, shard, allHunks);
        const projectionEvidencePath = projectionEvidencePathForShard(shard);
        const commands = verificationCommandsForSources(
          shard.sources,
          shard.testFiles,
          { evidencePath: projectionEvidencePath },
        );
        runVerificationCommands(
          commands,
          options.verificationRunner ?? spawnSync,
          childEnvironment,
        );
        shard.classification = "verification-only";
        shard.result = {
          audits,
          commands: commandList,
          ...(projectionEvidencePath
            ? {
                projectionEvidence: validatePoolProjectionEvidence(
                  JSON.parse(readFileSync(projectionEvidencePath, "utf8")),
                  readFileSync(POOL_PROJECTION_SOURCE, "utf8"),
                ),
              }
            : {}),
          tests: shard.testFiles,
        };
        console.log(`mutation-scope: verified non-mutatable source bundle ${shard.id}`);
      } else {
        validateScoredMutationReport(report, shard.config.thresholds.break, shard.id);
        shard.classification = "scored";
        shard.result = result.status === 0 ? "passed" : "failed";
      }
      if (result.status !== 0) throw Object.assign(new Error(`mutation shard ${shard.id} failed`), { status: result.status ?? 1 });
      const timingDecision = shard.cacheDecision === "rejected" ? "rejected" : "executed";
      const timing = finishShard(performanceRun, performanceToken, timingDecision, {
        classification: shard.classification,
        result: "passed",
        ...(timingDecision === "rejected" ? {
          rejectionReason: shard.reason,
          ...(shard.priorDurationMs === null ? {} : { priorDurationMs: shard.priorDurationMs }),
        } : {}),
      });
      shard.durationMs = timing.durationMs;
      if (shard.cacheDecision === "pending") shard.cacheDecision = "executed";
      if (cacheMode === "enabled" && shard.reason !== "runtime-profile-unavailable"
          && executionInputs.reusable) {
        const artifacts = { "mutation-report.json": shard.jsonReportPath };
        const artifactProjectors = {
          "mutation-report.json": projectMutationReportArtifact,
        };
        const projectionPath = projectionEvidencePathForShard(shard);
        if (projectionPath && existsSync(projectionPath)) {
          artifacts["projection-evidence.json"] = projectionPath;
          const sourceContents = readFileSync(POOL_PROJECTION_SOURCE, "utf8");
          artifactProjectors["projection-evidence.json"] = (evidence) =>
            validatePoolProjectionEvidence(evidence, sourceContents);
        }
        writeSuccessfulCacheEntry({
          root: repositoryCacheRoot,
          evidenceKey: shard.evidenceKey,
          entry: {
            result: "passed", shardKind: shard.kind, classification: shard.classification,
            durationMs: shard.durationMs, toolVersions, runtimeProfile,
            dependencyHashes: shard.dependencyHashes, commandList,
          },
          artifacts,
          artifactProjectors,
        });
      }
      persist();
      if (databaseSandboxRecord) {
        await cleanupDatabaseSandbox(databaseSandboxRecord);
      }
    }
    finishPerformanceRun(performanceRun, "passed");
    persist();
    return { manifest: manifestFor(), performance: performanceRun };
  } catch (err) {
    // A non-zero Stryker exit IS the gate failing — propagate the code, but not
    // execFileSync's exception: an uncaught throw prints a JS stack trace after
    // Stryker's own report, which reads as "the tool is broken" rather than
    // "your mutation score is short".
    if (err?.message) console.error(`mutation-scope: ${err.message}`);
    try {
      finishPerformanceRun(performanceRun, "failed");
      persist();
    } catch { /* retain the original mutation failure */ }
    throw err;
  }
  } finally {
    await cleanupAllDatabaseSandboxes();
    for (const [signal, handler] of signalHandlers) signalProcess.removeListener(signal, handler);
    for (const [key, value] of Object.entries(previousEnvironment)) {
      if (value === undefined) delete process.env[key];
      else process.env[key] = value;
    }
    if (options.cwd) process.chdir(previousCwd);
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try {
    await runMutationScope();
  } catch (error) {
    if (error?.message) console.error(`mutation-scope: ${error.message}`);
    process.exit(typeof error?.status === "number" ? error.status : 1);
  }
}
